from pathlib import Path
import re,json,html,zipfile,hashlib
from PIL import Image
r=Path(__file__).resolve().parents[1]
h=html.escape
# Correct only file extensions; preserve the original Nano Banana pixels.
for p in (r/'dum-e-odisha').glob('*.png'):
 with Image.open(p) as im:fmt=im.format
 if fmt=='JPEG':p.rename(p.with_suffix('.jpg'))
assets=[('dum-e-odisha-primary-tagline','Primary + tagline','Use for launch graphics, larger packaging labels and clear brand introductions.'),('dum-e-odisha-core-final','Core logo','The full brand name without the tagline. Use where the tagline would become too small.'),('dum-e-odisha-black','Black','Single-colour option for white backgrounds.'),('dum-e-odisha-white','White','Reversed single-colour option for black backgrounds.')]
manifest=[]
for stem,label,use in assets+[('dum-e-odisha-identity-board','Identity board','Illustrative brand presentation; not a logo master or print packaging file.')]:
 candidates=[r/'dum-e-odisha'/(stem+ext) for ext in ['.jpg','.png']];p=next((p for p in candidates if p.exists()),None);assert p,stem
 with Image.open(p) as im:fmt=im.format;w,hh=im.size
 manifest.append({'stem':stem,'label':label,'use':use,'file':p.relative_to(r).as_posix(),'width':w,'height':hh,'format':fmt,'transparent':False,'generator':'Nano Banana MCP','sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
(r/'dum-e-odisha/manifest.json').write_text(json.dumps(manifest,indent=2))
byname={a['stem']:a for a in manifest}
def img(stem,alt=None,cl=''):
 a=byname[stem];return f'<img class="{cl}" src="{a["file"]}" width="{a["width"]}" height="{a["height"]}" alt="{h(alt or "Dum E Odisha — "+a["label"])}">'
def link(stem):
 a=byname[stem];return f'<a href="{a["file"]}" download>Download {a["label"].lower()} · {a["format"]} · {a["width"]} × {a["height"]}</a>'
skills=[
('Rampstack logo design','https://github.com/rampstackco/claude-skills/blob/main/skills/logo-design/SKILL.md','Separate primary, compact and monochrome uses; keep one clear wordmark idea.','Named variants and application rules replace a set of equally ranked colour experiments.'),
('zstvns design skills','https://github.com/zstvns/design-skills','Assess Simple, Appropriate and Distinct in context; keep fixed core and flexible use separate.','Full-name hierarchy repaired; distinctiveness remains unscored without a confirmed direct competitor set.'),
('Magnus919 brand designer','https://github.com/magnus919/agent-skills/blob/main/brand-designer/SKILL.md','Document strategy, visual identity, voice, usage and inventory together.','One identity record, named asset manifest and an explicit current-versus-history split.'),
('Ziguishian brand design','https://github.com/ziguishian/brand-design-skill/blob/main/SKILL.md','Preserve the selected image source and show usable logo specifications.','Nano Banana reference-based refinement; clear-space, positive/negative, small-use and application panels.'),
('Atypica logo design','https://github.com/atypica-ai/marketing-skills/blob/main/skills/logo-design/SKILL.md','Analyse letter hierarchy, spacing, restrained colours and monochrome usability.','ODISHA promoted into the main name; generated letters checked visually; two logo inks selected.'),
('SanbaoAI logo generator','https://github.com/SanbaoAI/logo-generator-skill','Preserve silhouette when recolouring and prove the identity in relevant scenarios.','Colour roles tied to the lid and lettering; a food-packaging presentation instead of unrelated mockups. Mascot route reviewed and excluded because the selected mark is typographic.'),
('rknall SVG logo designer','https://github.com/rknall/claude-skills/blob/main/svg-logo-designer/SKILL.md','Plan lockups, backgrounds, clear space and organised delivery.','Usage variants and file organisation applied; SVG construction not used because the user requested Nano Banana only.'),
('Anthropic canvas design','https://github.com/anthropics/skills/blob/main/skills/canvas-design/SKILL.md','Begin with a visual philosophy; make hierarchy, space and colour carry the composition.','Shared Warmth philosophy and a visual identity canvas with restrained text. Rendering remains Nano Banana-generated, following the user’s tool choice.')]
findings=[
('Creative direction','The warm cooking-lid idea fitted the brief, but its intent was spread across competing studies.','Keep the chosen wordmark and define the emotional target as welcoming and appetising.','Documented; a full founder strategy workshop has not been conducted.'),
('Colour','Three multi-colour routes and several single-colour studies were presented without a stable everyday palette.','Use two logo inks: chilli for letters and saffron for lid/rice. Keep dark neutrals for supporting copy.','Targets specified; generated pixels are approximate.'),
('Logo','BIRYANI was the large second line and ODISHA was a tiny location label. That represented the wrong brand.','Remove BIRYANI from the logo; make ODISHA a prominent part of Dum E Odisha. Add a separate tagline version.','Corrected name and tagline checked visually in the delivered images.'),
('Pattern and texture','No consistent graphic device existed; adding decorative motifs would introduce noise.','Use clean fields and the selected lid/rice idea. Do not invent folk patterns, extra spices or texture.','Deliberate restraint; no separate pattern library is delivered.'),
('Typography and layout','The name hierarchy was wrong; the guide read mainly as an equal-weight card gallery.','Prioritise the complete name, then tagline. Use measured rule panels, a table of contents and actual supporting type samples.','Guide rebuilt; generated logo lettering is not a named or licensed typeface.'),
('Graphics','Only isolated logo renders were available; applications did not demonstrate the correct name.','Provide a compact identity canvas with food-container and carry-bag studies.','Illustrative proof of use, not production packaging artwork.'),
('Icons','The full wordmark cannot be read as a 16 px favicon. The first new profile attempt added an unrequested pepper.','Reject the drift; reuse the cleaned tagline-free core file for the profile. Do not claim a 16 px icon.','Small favicon remains out of scope; profile requires actual-size checking.'),
('Application','Earlier assets carried the wrong name into every touchpoint.','Only corrected Dum E Odisha files are linked in the current download. Older names are labelled superseded in history.','Current asset links and package contents validated.'),
('Style guide','Old and current studies coexisted without enough separation between rules, proposals and history.','Create one current guide, linked audit and clearly labelled archive. Record fixed colour roles, naming, voice and delivery limits.','Current content and file references checked; historical source images retained.')]
